# Generic helper to paginate through Spotify library endpoints
access_token = apis.spotify.login(
    username=main_user.spotify_username,
    password=main_user.spotify_password
).access_token

def fetch_all(fetch_page):
    items = []
    page_index = 0
    while True:
        page = fetch_page(access_token=access_token, page_index=page_index)
        if not page:
            break
        items.extend(page)
        page_index += 1
    return items

library_songs = fetch_all(apis.spotify.show_song_library)
library_albums = fetch_all(apis.spotify.show_album_library)
downloaded = fetch_all(apis.spotify.show_downloaded_songs)
liked_songs = fetch_all(apis.spotify.show_liked_songs)
liked_albums = fetch_all(apis.spotify.show_liked_albums)

downloaded_ids = {s['song_id'] for s in downloaded}
liked_song_ids = {s['song_id'] for s in liked_songs}
liked_album_ids = {a['album_id'] for a in liked_albums}

# For 'and' condition use `and`, for 'or' use `or`
for song in library_songs:
    keep = (song['song_id'] in downloaded_ids) or (song['song_id'] in liked_song_ids)
    if not keep:
        apis.spotify.remove_song_from_library(access_token=access_token, song_id=song['song_id'])

for album in library_albums:
    is_downloaded = all(sid in downloaded_ids for sid in album['song_ids'])
    is_liked = album['album_id'] in liked_album_ids
    keep = is_downloaded or is_liked
    if not keep:
        apis.spotify.remove_album_from_library(access_token=access_token, album_id=album['album_id'])
